# T-Display K230 keyboard yellow-symbol layer.
# Unspecified Shift combinations retain the Linux console defaults.

shift keycode  16 = apostrophe
shift keycode  17 = asciitilde
shift keycode  18 = minus
shift keycode  19 = plus
shift keycode  20 = equal
shift keycode  21 = backslash
shift keycode  22 = bar
shift keycode  23 = semicolon
shift keycode  24 = colon
shift keycode  25 = quotedbl

shift keycode  30 = asciitilde
shift keycode  31 = bracketleft
shift keycode  32 = bracketright
shift keycode  33 = braceleft
shift keycode  34 = braceright
shift keycode  35 = comma
shift keycode  36 = grave
shift keycode  37 = slash
shift keycode  38 = question

shift keycode  48 = period
shift keycode  49 = less
shift keycode  50 = greater
